  ('global_cause_convenience', 'GLOBAL', null, null, 'CAUSE', array['원인', '이유', '배경', '어려운 이유', '많아진 이유', '발생 원인']::text[], '편리함을 우선하다', 'Ưu tiên sự tiện lợi', '사람들은 장기적인 이익보다 당장의 편리함을 선택하기 쉽기 때문이다.', 'Vì con người dễ chọn sự tiện lợi trước mắt hơn lợi ích dài hạn.', '좋은 습관이나 필요한 행동을 꾸준히 실천하지 못할 수 있다.', 'Có thể không duy trì được thói quen tốt hoặc hành động cần thiết.', null, null, '["즉각적 편리함","장기 이익 무시","실천 감소","문제 지속"]'::jsonb, '["tiện lợi trước mắt","bỏ qua lợi ích dài hạn","giảm thực hiện","vấn đề kéo dài"]'::jsonb, '["편리함을 우선하다","장기적으로 생각하다","꾸준히 실천하다"]'::jsonb, 5, 'NORMAL', '[]'::jsonb, 'PUBLIC', 'PUBLISHED', 'MANUAL'),
  ('global_cause_system', 'GLOBAL', null, null, 'CAUSE', array['원인', '이유', '배경', '어려운 이유', '많아진 이유', '발생 원인']::text[], '제도와 관리가 부족하다', 'Thiếu hệ thống và quản lý', '개인의 노력만으로는 문제를 지속적으로 관리하기 어렵기 때문이다.', 'Vì chỉ nỗ lực cá nhân thì khó quản lý vấn đề lâu dài.', '명확한 기준과 지원이 없으면 참여율도 낮아질 수 있다.', 'Nếu thiếu tiêu chuẩn và hỗ trợ rõ ràng, tỷ lệ tham gia có thể thấp.', null, null, '["관리 체계 부족","기준 부족","지원 부족","참여 저하"]'::jsonb, '["thiếu quản lý","thiếu tiêu chuẩn","thiếu hỗ trợ","giảm tham gia"]'::jsonb, '["제도가 부족하다","관리 체계를 마련하다","기준을 마련하다"]'::jsonb, 5, 'NORMAL', '[]'::jsonb, 'PUBLIC', 'PUBLISHED', 'MANUAL'),
  ('global_solution_awareness', 'GLOBAL', null, null, 'SOLUTION', array['노력', '해결 방안', '방법', '방향', '바람직한 태도', '올바른 태도', '어떻게 해야 하는가']::text[], '인식을 높이다', 'Nâng cao nhận thức', '교육과 홍보를 통해 문제의 중요성과 올바른 방법을 알려야 한다.', 'Cần dùng giáo dục và truyền thông để cho biết tầm quan trọng và cách đúng.', '사람들이 스스로 필요성을 이해하면 자발적인 참여가 늘어날 수 있다.', 'Khi tự hiểu sự cần thiết, sự tham gia tự nguyện có thể tăng.', null, null, '["교육·홍보","인식 향상","자발적 참여","행동 변화"]'::jsonb, '["giáo dục/truyền thông","tăng nhận thức","tham gia tự nguyện","thay đổi hành vi"]'::jsonb, '["인식을 높이다","교육을 강화하다","홍보를 확대하다"]'::jsonb, 5, 'NORMAL', '[]'::jsonb, 'PUBLIC', 'PUBLISHED', 'MANUAL'),
  ('global_solution_goals', 'GLOBAL', null, null, 'SOLUTION', array['노력', '해결 방안', '방법', '방향', '바람직한 태도', '올바른 태도', '어떻게 해야 하는가']::text[], '구체적인 목표를 세우다', 'Đặt mục tiêu cụ thể', '막연한 계획보다 실천 가능한 목표가 행동을 지속하는 데 도움이 되기 때문이다.', 'Vì mục tiêu khả thi giúp duy trì hành động tốt hơn kế hoạch mơ hồ.', '작은 성과를 확인하면서 꾸준히 실천하기 쉬워진다.', 'Dễ duy trì khi có thể thấy các thành quả nhỏ.', null, null, '["구체적 목표","작은 실천","성과 확인","꾸준한 행동"]'::jsonb, '["mục tiêu cụ thể","hành động nhỏ","thấy thành quả","duy trì đều đặn"]'::jsonb, '["목표를 세우다","꾸준히 실천하다","성과를 확인하다"]'::jsonb, 5, 'NORMAL', '[]'::jsonb, 'PUBLIC', 'PUBLISHED', 'MANUAL'),
  ('global_solution_support', 'GLOBAL', null, null, 'SOLUTION', array['노력', '해결 방안', '방법', '방향', '바람직한 태도', '올바른 태도', '어떻게 해야 하는가']::text[], '지원을 강화하다', 'Tăng cường hỗ trợ', '개인이 혼자 해결하기 어려운 부분을 제도적·경제적으로 도울 필요가 있기 때문이다.', 'Vì cần hỗ trợ về hệ thống hoặc kinh tế cho phần cá nhân khó tự giải quyết.', '참여 장벽이 낮아져 더 많은 사람이 실천할 수 있다.', 'Rào cản tham gia giảm, nhiều người hơn có thể thực hiện.', null, null, '["지원 확대","부담 감소","참여 장벽 완화","참여 증가"]'::jsonb, '["mở rộng hỗ trợ","giảm gánh nặng","giảm rào cản","tăng tham gia"]'::jsonb, '["지원을 강화하다","부담을 줄이다","참여를 확대하다"]'::jsonb, 5, 'NORMAL', '[]'::jsonb, 'PUBLIC', 'PUBLISHED', 'MANUAL'),
  ('global_solution_system', 'GLOBAL', null, null, 'SOLUTION', array['노력', '해결 방안', '방법', '방향', '바람직한 태도', '올바른 태도', '어떻게 해야 하는가']::text[], '제도를 개선하다', 'Cải thiện hệ thống', '지속적인 문제 해결을 위해서는 명확한 기준과 절차가 필요하기 때문이다.', 'Vì giải quyết lâu dài cần tiêu chuẩn và quy trình rõ ràng.', '개인의 노력에만 의존하지 않고 안정적으로 문제를 관리할 수 있다.', 'Có thể quản lý ổn định mà không chỉ dựa vào nỗ lực cá nhân.', null, null, '["기준 마련","제도 개선","지속적 관리","문제 감소"]'::jsonb, '["xây tiêu chuẩn","cải thiện hệ thống","quản lý liên tục","giảm vấn đề"]'::jsonb, '["제도를 개선하다","기준을 마련하다","문제를 관리하다"]'::jsonb, 5, 'NORMAL', '[]'::jsonb, 'PUBLIC', 'PUBLISHED', 'MANUAL'),
  ('global_solution_management', 'GLOBAL', null, null, 'SOLUTION', array['노력', '해결 방안', '방법', '방향', '바람직한 태도', '올바른 태도', '어떻게 해야 하는가']::text[], '관리를 강화하다', 'Tăng cường quản lý', '규칙이 있어도 제대로 관리하지 않으면 실효성이 떨어질 수 있기 때문이다.', 'Vì quy định sẽ kém hiệu quả nếu không được quản lý đúng.', '문제를 조기에 발견하고 반복되는 피해를 줄일 수 있다.', 'Có thể phát hiện sớm và giảm thiệt hại lặp lại.', null, null, '["관리 강화","조기 발견","신속 대응","피해 감소"]'::jsonb, '["tăng quản lý","phát hiện sớm","ứng phó nhanh","giảm thiệt hại"]'::jsonb, '["관리를 강화하다","문제를 발견하다","피해를 줄이다"]'::jsonb, 5, 'NORMAL', '[]'::jsonb, 'PUBLIC', 'PUBLISHED', 'MANUAL'),
  ('global_solution_cooperation', 'GLOBAL', null, null, 'SOLUTION', array['노력', '해결 방안', '방법', '방향', '바람직한 태도', '올바른 태도', '어떻게 해야 하는가']::text[], '서로 협력하다', 'Hợp tác với nhau', '복잡한 문제는 개인이나 한 기관만의 노력으로 해결하기 어렵기 때문이다.', 'Vì vấn đề phức tạp khó giải quyết chỉ bằng một cá nhân hoặc cơ quan.', '개인·기업·정부가 역할을 나누면 더 효과적으로 해결할 수 있다.', 'Nếu cá nhân, doanh nghiệp và chính phủ chia sẻ vai trò thì giải quyết hiệu quả hơn.', null, null, '["역할 분담","상호 협력","공동 대응","해결 효과 향상"]'::jsonb, '["chia sẻ vai trò","hợp tác","ứng phó chung","tăng hiệu quả giải quyết"]'::jsonb, '["서로 협력하다","역할을 나누다","공동으로 해결하다"]'::jsonb, 5, 'NORMAL', '[]'::jsonb, 'PUBLIC', 'PUBLISHED', 'MANUAL'),
  ('environment_positive_pollution', 'TOPIC', (select id from public.q54_topics where slug = 'environment'), null, 'POSITIVE', array['장점', '필요성', '중요성', '긍정적인 영향', '도움', '효과', '성과']::text[], '환경 오염을 줄이다', 'Giảm ô nhiễm môi trường', '친환경적인 생활과 정책은 오염 물질의 발생량을 줄이는 데 도움이 되기 때문이다.', 'Vì lối sống và chính sách thân thiện môi trường giúp giảm lượng chất ô nhiễm.', '공기와 물이 깨끗해져 더 안전한 생활 환경을 만들 수 있다.', 'Không khí và nước sạch hơn, tạo môi trường sống an toàn hơn.', null, null, '["친환경 실천","오염 물질 감소","환경 오염 감소","생활 환경 개선"]'::jsonb, '["thực hành xanh","giảm chất ô nhiễm","giảm ô nhiễm","cải thiện môi trường sống"]'::jsonb, '["환경 오염을 줄이다","오염 물질을 줄이다","생활 환경을 개선하다"]'::jsonb, 5, 'NORMAL', '["환경","기후 변화","친환경 생활"]'::jsonb, 'PUBLIC', 'PUBLISHED', 'MANUAL'),
  ('environment_positive_resources', 'TOPIC', (select id from public.q54_topics where slug = 'environment'), null, 'POSITIVE', array['장점', '필요성', '중요성', '긍정적인 영향', '도움', '효과', '성과']::text[], '자원을 절약하다', 'Tiết kiệm tài nguyên', '재사용과 재활용을 늘리면 새로운 자원의 소비를 줄일 수 있기 때문이다.', 'Vì tăng tái sử dụng và tái chế giúp giảm tiêu thụ tài nguyên mới.', '한정된 자원을 더 오래 사용할 수 있고 자원 낭비도 줄어든다.', 'Có thể dùng tài nguyên hữu hạn lâu hơn và giảm lãng phí.', null, null, '["재사용·재활용","자원 소비 감소","자원 절약","낭비 감소"]'::jsonb, '["tái sử dụng/tái chế","giảm tiêu thụ","tiết kiệm tài nguyên","giảm lãng phí"]'::jsonb, '["자원을 절약하다","재활용을 늘리다","자원 낭비를 줄이다"]'::jsonb, 5, 'NORMAL', '["환경","기후 변화","친환경 생활"]'::jsonb, 'PUBLIC', 'PUBLISHED', 'MANUAL'),
  ('environment_positive_health', 'TOPIC', (select id from public.q54_topics where slug = 'environment'), null, 'POSITIVE', array['장점', '필요성', '중요성', '긍정적인 영향', '도움', '효과', '성과']::text[], '건강을 보호하다', 'Bảo vệ sức khỏe', '대기와 수질 오염은 사람들의 건강에 직접적인 영향을 미치기 때문이다.', 'Vì ô nhiễm không khí và nước ảnh hưởng trực tiếp đến sức khỏe.', '오염을 줄이면 호흡기 질환 등 건강 문제의 위험을 낮출 수 있다.', 'Giảm ô nhiễm giúp hạ nguy cơ các vấn đề sức khỏe như bệnh hô hấp.', null, null, '["오염 감소","유해 물질 감소","질병 위험 감소","건강 보호"]'::jsonb, '["giảm ô nhiễm","giảm chất độc hại","giảm nguy cơ bệnh","bảo vệ sức khỏe"]'::jsonb, '["건강을 보호하다","질병 위험을 줄이다","부정적인 영향을 미치다"]'::jsonb, 5, 'NORMAL', '["환경","기후 변화","친환경 생활"]'::jsonb, 'PUBLIC', 'PUBLISHED', 'MANUAL'),
  ('environment_positive_ecosystem', 'TOPIC', (select id from public.q54_topics where slug = 'environment'), null, 'POSITIVE', array['장점', '필요성', '중요성', '긍정적인 영향', '도움', '효과', '성과']::text[], '생태계를 보전하다', 'Bảo tồn hệ sinh thái', '환경 오염과 무분별한 개발은 동식물의 서식지를 파괴할 수 있기 때문이다.', 'Vì ô nhiễm và phát triển thiếu kiểm soát có thể phá hủy môi trường sống của sinh vật.', '생물 다양성을 유지하고 자연환경의 균형을 지키는 데 도움이 된다.', 'Giúp duy trì đa dạng sinh học và cân bằng tự nhiên.', null, null, '["서식지 보호","생태계 보전","생물 다양성 유지","자연 균형"]'::jsonb, '["bảo vệ nơi sống","bảo tồn hệ sinh thái","duy trì đa dạng sinh học","cân bằng tự nhiên"]'::jsonb, '["생태계를 보전하다","서식지를 보호하다","생물 다양성을 유지하다"]'::jsonb, 5, 'NORMAL', '["환경","기후 변화","친환경 생활"]'::jsonb, 'PUBLIC', 'PUBLISHED', 'MANUAL'),
