  ('environment_cause_policy', 'TOPIC', (select id from public.q54_topics where slug = 'environment'), null, 'CAUSE', array['원인', '이유', '배경', '어려운 이유', '많아진 이유', '발생 원인']::text[], '관련 정책과 관리가 부족하다', 'Thiếu chính sách và quản lý liên quan', '개인의 자발적인 노력만으로는 대규모 환경 문제를 줄이기 어렵기 때문이다.', 'Vì chỉ nỗ lực tự nguyện của cá nhân khó giảm vấn đề môi trường quy mô lớn.', '명확한 기준이 없으면 기업과 시민의 참여도 낮아질 수 있다.', 'Nếu thiếu tiêu chuẩn rõ ràng, sự tham gia của doanh nghiệp và người dân có thể thấp.', null, null, '["정책 부족","관리 기준 부족","참여 감소","환경 문제 지속"]'::jsonb, '["thiếu chính sách","thiếu tiêu chuẩn","giảm tham gia","vấn đề kéo dài"]'::jsonb, '["환경 정책을 마련하다","관리를 강화하다","기준을 마련하다"]'::jsonb, 5, 'NORMAL', '["환경","기후 변화","친환경 생활"]'::jsonb, 'PUBLIC', 'PUBLISHED', 'MANUAL'),
  ('environment_solution_disposable', 'TOPIC', (select id from public.q54_topics where slug = 'environment'), null, 'SOLUTION', array['노력', '해결 방안', '방법', '방향', '바람직한 태도', '올바른 태도', '어떻게 해야 하는가']::text[], '일회용품 사용을 줄이다', 'Giảm sử dụng đồ dùng một lần', '재사용 가능한 제품을 선택하면 쓰레기와 자원 소비를 동시에 줄일 수 있다.', 'Nếu chọn sản phẩm tái sử dụng, có thể giảm rác và tiêu thụ tài nguyên.', '개인의 작은 실천이 모이면 환경 부담을 줄이는 데 도움이 된다.', 'Khi các hành động nhỏ được cộng lại, có thể giảm gánh nặng môi trường.', null, null, '["재사용 제품 선택","일회용품 감소","쓰레기 감소","환경 부담 감소"]'::jsonb, '["chọn đồ tái dùng","giảm đồ một lần","giảm rác","giảm gánh nặng môi trường"]'::jsonb, '["일회용품 사용을 줄이다","재사용하다","쓰레기를 줄이다"]'::jsonb, 5, 'NORMAL', '["환경","기후 변화","친환경 생활"]'::jsonb, 'PUBLIC', 'PUBLISHED', 'MANUAL'),
  ('environment_solution_transport', 'TOPIC', (select id from public.q54_topics where slug = 'environment'), null, 'SOLUTION', array['노력', '해결 방안', '방법', '방향', '바람직한 태도', '올바른 태도', '어떻게 해야 하는가']::text[], '대중교통 이용을 늘리다', 'Tăng sử dụng giao thông công cộng', '자동차 이용을 줄이면 배출가스와 에너지 사용을 함께 줄일 수 있기 때문이다.', 'Vì giảm ô tô giúp giảm cả khí thải và sử dụng năng lượng.', '도시의 대기 질을 개선하고 교통 부담도 줄이는 데 도움이 된다.', 'Giúp cải thiện chất lượng không khí và giảm áp lực giao thông.', null, null, '["자동차 이용 감소","대중교통 확대","배출가스 감소","대기 질 개선"]'::jsonb, '["giảm ô tô","tăng giao thông công cộng","giảm khí thải","cải thiện không khí"]'::jsonb, '["대중교통을 이용하다","배출가스를 줄이다","대기 질을 개선하다"]'::jsonb, 5, 'NORMAL', '["환경","기후 변화","친환경 생활"]'::jsonb, 'PUBLIC', 'PUBLISHED', 'MANUAL'),
