  ('education_positive_career', 'TOPIC', (select id from public.q54_topics where slug = 'education-self-development'), null, 'POSITIVE', array['장점', '필요성', '중요성', '긍정적인 영향', '도움', '효과', '성과']::text[], '진로 선택에 도움이 되다', 'Hỗ trợ lựa chọn nghề nghiệp', '다양한 직업과 경험을 접하면 자신의 적성과 관심을 파악하기 쉬워지기 때문이다.', 'Vì tiếp xúc nhiều nghề và trải nghiệm giúp hiểu năng khiếu và sở thích.', '자신에게 더 잘 맞는 진로를 선택할 가능성이 높아진다.', 'Khả năng chọn con đường phù hợp bản thân cao hơn.', null, null, '["직업 경험","적성·관심 파악","진로 탐색","적절한 선택"]'::jsonb, '["trải nghiệm nghề","hiểu năng khiếu/sở thích","khám phá nghề","chọn phù hợp"]'::jsonb, '["진로를 선택하다","적성을 파악하다","관심을 알다"]'::jsonb, 5, 'NORMAL', '["교육","자기계발","온라인 학습","직업 체험","독서","창의력"]'::jsonb, 'PUBLIC', 'PUBLISHED', 'MANUAL'),
